import sys
d = sys.stdin.read().split()
n = int(d[0])
adj = {i: [] for i in range(1, n+1)}
for i in range(n-1):
    a, b = int(d[1+2*i]), int(d[2+2*i])
    adj[a].append(b)
    adj[b].append(a)
best = 0
for s in range(1, n+1):
    dd = {s: 0}
    q = [s]
    while q:
        x = q.pop(0)
        for y in adj[x]:
            if y not in dd:
                dd[y] = dd[x] + 1
                q.append(y)
    best = max(best, max(dd.values()))
print(best)

import sys
sys.setrecursionlimit(10000)
d = sys.stdin.read().split()
n, m = int(d[0]), int(d[1])
adj = {i: [] for i in range(1, n+1)}
for i in range(m):
    a, b = int(d[2+2*i]), int(d[3+2*i])
    adj[a].append(b)
    adj[b].append(a)
col = {}
def go(x, c):
    col[x] = c
    for y in adj[x]:
        if y in col:
            if col[y] == c:
                return False
        elif not go(y, 1 - c):
            return False
    return True
ok = all(go(s, 0) for s in range(1, n+1) if s not in col)
print("YES" if ok else "NO")

import sys
d = sys.stdin.read().split()
n, m = int(d[0]), int(d[1])
cap = {}
for i in range(m):
    a, b, c = int(d[2+3*i]), int(d[3+3*i]), int(d[4+3*i])
    cap[(a, b)] = cap.get((a, b), 0) + c
def dfs(x, seen, f):
    if x == n:
        return f
    seen.add(x)
    for y in range(1, n+1):
        c = cap.get((x, y), 0)
        if y not in seen and c > 0:
            r = dfs(y, seen, min(f, c))
            if r:
                cap[(x, y)] -= r
                cap[(y, x)] = cap.get((y, x), 0) + r
                return r
    return 0
flow = 0
while True:
    r = dfs(1, set(), 10**9)
    if not r:
        break
    flow += r
print(flow)

